import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import './Welcome.css';

function Welcome() {
  const navigate = useNavigate();
  const [showSkip, setShowSkip] = useState(false);
  const [videoEnded, setVideoEnded] = useState(false);
  const [currentVideo, setCurrentVideo] = useState(0);
  const videoRef1 = useRef(null);
  const videoRef2 = useRef(null);

  const videos = [
    "https://cdn.coverr.co/videos/coverr-making-sweets-5645/1080p.mp4",
    "https://cdn.coverr.co/videos/coverr-pouring-honey-on-pancakes-5774/1080p.mp4"
  ];

  useEffect(() => {
    // Show skip button after 3 seconds
    const timer = setTimeout(() => setShowSkip(true), 3000);
    return () => clearTimeout(timer);
  }, []);

  const handleVideoEnd = () => {
    if (currentVideo === 0) {
      // Play second video
      setCurrentVideo(1);
      if (videoRef2.current) {
        videoRef2.current.play().catch(() => {});
      }
    } else {
      setVideoEnded(true);
      // Auto redirect after both videos end
      setTimeout(() => navigate('/home'), 1500);
    }
  };

  const handleSkip = () => {
    navigate('/home');
  };

  return (
    <div className="welcome-page">
      {/* Video Container */}
      <div className="welcome-video-container">
        {/* First Video */}
        <video
          ref={videoRef1}
          autoPlay
          muted
          playsInline
          className={`welcome-video ${currentVideo === 0 ? 'active' : 'exiting'}`}
          onEnded={handleVideoEnd}
          onError={() => {
            // If first video fails, try second
            setCurrentVideo(1);
            if (videoRef2.current) videoRef2.current.play().catch(() => {});
          }}
        >
          <source src={videos[0]} type="video/mp4" />
        </video>

        {/* Second Video */}
        <video
          ref={videoRef2}
          muted
          playsInline
          className={`welcome-video ${currentVideo === 1 ? 'active' : ''}`}
          onEnded={handleVideoEnd}
          onError={() => {
            // If both videos fail, auto navigate
            setTimeout(() => navigate('/home'), 2000);
          }}
        >
          <source src={videos[1]} type="video/mp4" />
        </video>

        {/* Logo Overlay */}
        <div className="welcome-logo-overlay">
          <img 
            src="C:/Users/LENOVO/Downloads/WhatsApp Image 2026-07-23 at 12.15.41 PM.jpeg" 
            alt="Riddhi Siddhi Modak Farsan" 
            className="welcome-logo"
          />
        </div>

        {/* Skip Button */}
        {showSkip && !videoEnded && (
          <button className="welcome-skip-btn" onClick={handleSkip}>
            Skip ▶
          </button>
        )}

        {/* Loading/Redirecting Indicator */}
        {videoEnded && (
          <div className="welcome-redirecting">
            <div className="welcome-spinner"></div>
            <p>Taking you to our menu...</p>
          </div>
        )}
      </div>

      {/* Brand Name at Bottom */}
      <div className="welcome-brand">
        <h1>Riddhi Siddhi</h1>
        <p>Modak Farsan</p>
        <p className="welcome-tagline">✨ Shuddh Swad, Hamari Pehchaan ✨</p>
      </div>
    </div>
  );
}

export default Welcome;
